// Cloudflare Worker: simple accounts, cross-device progress sync and a friends leaderboard.
// Static files are served by Workers Static Assets; only /api/* reaches this code (run_worker_first).
// Progress is stored as an opaque gzip+base64 string the Worker never parses (keeps CPU tiny).

// `Env` (with the DB binding) is generated by `wrangler types` into worker-configuration.d.ts.

const PBKDF2_ITER = 6000;              // per-user and stored, so it can be raised later; free-plan CPU budget is ~10 ms
const SESSION_DAYS = 180;
const MAX_BLOB = 1_900_000;            // D1 row limit is 2 MB
const MAX_FRIENDS = 50;
const SIGNUPS_PER_IP_PER_DAY = 10;
const MAX_DAILY_POINTS = 5000;          // 12 questions × 50 + time bonus stays far below this

const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, salt TEXT NOT NULL, hash TEXT NOT NULL, iter INTEGER NOT NULL, friend_code TEXT NOT NULL UNIQUE, share INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, fails INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0)`,
  `CREATE TABLE IF NOT EXISTS tokens (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL)`,
  `CREATE INDEX IF NOT EXISTS tokens_user ON tokens(user_id)`,
  `CREATE TABLE IF NOT EXISTS progress (user_id INTEGER PRIMARY KEY, data TEXT NOT NULL, rev INTEGER NOT NULL, updated INTEGER NOT NULL, size INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS friends (user_id INTEGER NOT NULL, friend_id INTEGER NOT NULL, created INTEGER NOT NULL, PRIMARY KEY (user_id, friend_id))`,
  `CREATE TABLE IF NOT EXISTS scores (user_id INTEGER NOT NULL, day TEXT NOT NULL, points INTEGER NOT NULL, correct INTEGER NOT NULL, total INTEGER NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (user_id, day))`,
  `CREATE TABLE IF NOT EXISTS signups (ip TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (ip, day))`,
];
let schemaReady: Promise<unknown> | null = null;
const ensureSchema = (db: D1Database) => (schemaReady ??= db.batch(SCHEMA.map((s) => db.prepare(s))).catch((e) => { schemaReady = null; throw e; }));

// ---------- helpers ----------
const json = (body: unknown, status = 200, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store', ...headers } });
const err = (status: number, error: string, extra: Record<string, unknown> = {}) => json({ error, ...extra }, status);
const enc = new TextEncoder();
const b64 = (u: Uint8Array) => btoa(String.fromCharCode(...u));
const unb64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const hex = (buf: ArrayBuffer) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
const randomBytes = (n: number) => crypto.getRandomValues(new Uint8Array(n));
const sha256 = async (s: string) => hex(await crypto.subtle.digest('SHA-256', enc.encode(s)));
const today = () => new Date().toISOString().slice(0, 10);
const dayShift = (d: string, n: number) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 86400000).toISOString().slice(0, 10);

async function pbkdf2(pass: string, salt: Uint8Array, iter: number): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey('raw', enc.encode(pass), 'PBKDF2', false, ['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: iter }, key, 256));
}
function sameBytes(a: Uint8Array, b: Uint8Array) {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a[i] ^ b[i];
  return d === 0;
}
const FRIEND_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I
const friendCode = () => [...randomBytes(8)].map((b) => FRIEND_ALPHABET[b % FRIEND_ALPHABET.length]).join('');

const USERNAME_RE = /^[a-z0-9_.-]{3,24}$/i;
async function readJson<T>(req: Request): Promise<T | null> {
  try { return (await req.json()) as T; } catch { return null; }
}

interface User { id: number; username: string; share: number; friend_code: string }
async function authed(req: Request, env: Env): Promise<User | null> {
  const m = (req.headers.get('authorization') ?? '').match(/^Bearer ([A-Za-z0-9_-]{20,})$/);
  if (!m) return null;
  return env.DB.prepare(`SELECT u.id, u.username, u.share, u.friend_code FROM tokens t JOIN users u ON u.id = t.user_id WHERE t.token_hash = ? AND t.expires > ?`)
    .bind(await sha256(m[1]), Date.now()).first<User>();
}
async function issueToken(env: Env, userId: number) {
  const token = b64(randomBytes(32)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const now = Date.now();
  await env.DB.batch([
    env.DB.prepare(`INSERT INTO tokens (token_hash, user_id, created, expires) VALUES (?, ?, ?, ?)`).bind(await sha256(token), userId, now, now + SESSION_DAYS * 86400000),
    env.DB.prepare(`DELETE FROM tokens WHERE expires < ?`).bind(now),
  ]);
  return token;
}
const publicUser = (u: User) => ({ username: u.username, friendCode: u.friend_code, share: !!u.share });

// ---------- routes ----------
async function signup(req: Request, env: Env) {
  const body = await readJson<{ username?: string; passphrase?: string }>(req);
  const username = (body?.username ?? '').trim(), pass = body?.passphrase ?? '';
  if (!USERNAME_RE.test(username)) return err(400, 'Username must be 3–24 characters: letters, numbers, _ . -');
  if (pass.length < 8 || pass.length > 200) return err(400, 'Passphrase must be at least 8 characters.');
  const ip = req.headers.get('cf-connecting-ip') ?? 'local';
  const day = today();
  const used = await env.DB.prepare(`SELECT n FROM signups WHERE ip = ? AND day = ?`).bind(ip, day).first<{ n: number }>();
  if ((used?.n ?? 0) >= SIGNUPS_PER_IP_PER_DAY) return err(429, 'Too many new accounts from this network today. Try again tomorrow.');
  if (await env.DB.prepare(`SELECT 1 FROM users WHERE username = ?`).bind(username).first()) return err(409, 'That username is taken.');
  const salt = randomBytes(16);
  const hash = await pbkdf2(pass, salt, PBKDF2_ITER);
  let user: User | null = null;
  for (let i = 0; i < 3 && !user; i++) {
    try {
      user = await env.DB.prepare(`INSERT INTO users (username, salt, hash, iter, friend_code, created) VALUES (?, ?, ?, ?, ?, ?) RETURNING id, username, share, friend_code`)
        .bind(username, b64(salt), b64(hash), PBKDF2_ITER, friendCode(), Date.now()).first<User>();
    } catch (e) {
      if (/username/i.test(String(e))) return err(409, 'That username is taken.');
      if (!/friend_code|UNIQUE/i.test(String(e))) throw e; // friend-code collision: retry
    }
  }
  if (!user) return err(500, 'Could not create the account. Please try again.');
  await env.DB.prepare(`INSERT INTO signups (ip, day, n) VALUES (?, ?, 1) ON CONFLICT(ip, day) DO UPDATE SET n = n + 1`).bind(ip, day).run();
  return json({ token: await issueToken(env, user.id), user: publicUser(user) }, 201);
}

async function login(req: Request, env: Env) {
  const body = await readJson<{ username?: string; passphrase?: string }>(req);
  const username = (body?.username ?? '').trim(), pass = body?.passphrase ?? '';
  const row = await env.DB.prepare(`SELECT id, username, share, friend_code, salt, hash, iter, fails, locked_until FROM users WHERE username = ?`).bind(username)
    .first<User & { salt: string; hash: string; iter: number; fails: number; locked_until: number }>();
  const generic = err(401, 'Wrong username or passphrase.');
  if (!row || !pass) return generic;
  const now = Date.now();
  if (row.locked_until > now) return err(429, `Too many attempts. Try again in ${Math.ceil((row.locked_until - now) / 1000)} s.`);
  const ok = sameBytes(await pbkdf2(pass, unb64(row.salt), row.iter), unb64(row.hash));
  if (!ok) {
    const fails = row.fails + 1;
    const lock = fails >= 5 ? now + Math.min(3600, 30 * 2 ** (fails - 5)) * 1000 : 0;
    await env.DB.prepare(`UPDATE users SET fails = ?, locked_until = ? WHERE id = ?`).bind(fails, lock, row.id).run();
    return generic;
  }
  if (row.fails) await env.DB.prepare(`UPDATE users SET fails = 0, locked_until = 0 WHERE id = ?`).bind(row.id).run();
  return json({ token: await issueToken(env, row.id), user: publicUser(row) });
}

async function getSync(env: Env, u: User) {
  const row = await env.DB.prepare(`SELECT data, rev, updated FROM progress WHERE user_id = ?`).bind(u.id).first<{ data: string; rev: number; updated: number }>();
  if (!row) return new Response(null, { status: 204, headers: { 'x-rev': '0', 'cache-control': 'no-store' } });
  return new Response(row.data, { headers: { 'content-type': 'text/plain', 'x-rev': String(row.rev), 'x-updated': String(row.updated), 'cache-control': 'no-store' } });
}

async function putSync(req: Request, env: Env, u: User) {
  const base = Number(req.headers.get('x-base-rev') ?? '-1');
  const data = await req.text();
  if (!data || data.length > MAX_BLOB) return err(413, 'Progress data is too large to sync.');
  if (!/^[A-Za-z0-9+/=]+$/.test(data.slice(0, 64))) return err(400, 'Expected base64-encoded data.');
  const now = Date.now();
  // optimistic concurrency: only write if nobody else wrote since this client last merged
  const res = base === 0
    ? await env.DB.prepare(`INSERT INTO progress (user_id, data, rev, updated, size) VALUES (?, ?, 1, ?, ?) ON CONFLICT(user_id) DO NOTHING`).bind(u.id, data, now, data.length).run()
    : await env.DB.prepare(`UPDATE progress SET data = ?, rev = rev + 1, updated = ?, size = ? WHERE user_id = ? AND rev = ?`).bind(data, now, data.length, u.id, base).run();
  const cur = await env.DB.prepare(`SELECT rev FROM progress WHERE user_id = ?`).bind(u.id).first<{ rev: number }>();
  if (!res.meta.changes) return err(409, 'Progress changed on another device. Merge and retry.', { rev: cur?.rev ?? 0 });
  return json({ rev: cur?.rev ?? 1, updated: now });
}

async function updateMe(req: Request, env: Env, u: User) {
  const body = await readJson<{ share?: boolean }>(req);
  if (typeof body?.share === 'boolean') await env.DB.prepare(`UPDATE users SET share = ? WHERE id = ?`).bind(body.share ? 1 : 0, u.id).run();
  return json({ user: publicUser({ ...u, share: typeof body?.share === 'boolean' ? Number(body.share) : u.share }) });
}

async function deleteAccount(req: Request, env: Env, u: User) {
  const body = await readJson<{ passphrase?: string }>(req);
  const row = await env.DB.prepare(`SELECT salt, hash, iter FROM users WHERE id = ?`).bind(u.id).first<{ salt: string; hash: string; iter: number }>();
  if (!row || !body?.passphrase || !sameBytes(await pbkdf2(body.passphrase, unb64(row.salt), row.iter), unb64(row.hash))) return err(401, 'Wrong passphrase.');
  await env.DB.batch([
    env.DB.prepare(`DELETE FROM progress WHERE user_id = ?`).bind(u.id),
    env.DB.prepare(`DELETE FROM tokens WHERE user_id = ?`).bind(u.id),
    env.DB.prepare(`DELETE FROM friends WHERE user_id = ? OR friend_id = ?`).bind(u.id, u.id),
    env.DB.prepare(`DELETE FROM scores WHERE user_id = ?`).bind(u.id),
    env.DB.prepare(`DELETE FROM users WHERE id = ?`).bind(u.id),
  ]);
  return json({ ok: true });
}

// ---------- friends & leaderboard ----------
async function listFriends(env: Env, u: User) {
  const { results } = await env.DB.prepare(`SELECT u.username, u.share FROM friends f JOIN users u ON u.id = f.friend_id WHERE f.user_id = ? ORDER BY u.username COLLATE NOCASE`).bind(u.id).all<{ username: string; share: number }>();
  return json({ me: publicUser(u), friends: results.map((r) => ({ username: r.username, sharing: !!r.share })) });
}

async function addFriend(req: Request, env: Env, u: User) {
  const body = await readJson<{ code?: string }>(req);
  const code = (body?.code ?? '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (code.length !== 8) return err(400, 'Friend codes are 8 characters.');
  const f = await env.DB.prepare(`SELECT id, username FROM users WHERE friend_code = ?`).bind(code).first<{ id: number; username: string }>();
  if (!f) return err(404, 'No one has that friend code.');
  if (f.id === u.id) return err(400, 'That is your own friend code.');
  const n = await env.DB.prepare(`SELECT COUNT(*) AS n FROM friends WHERE user_id = ?`).bind(u.id).first<{ n: number }>();
  if ((n?.n ?? 0) >= MAX_FRIENDS) return err(400, `You can have up to ${MAX_FRIENDS} friends.`);
  const now = Date.now();
  await env.DB.batch([
    env.DB.prepare(`INSERT OR IGNORE INTO friends (user_id, friend_id, created) VALUES (?, ?, ?)`).bind(u.id, f.id, now),
    env.DB.prepare(`INSERT OR IGNORE INTO friends (user_id, friend_id, created) VALUES (?, ?, ?)`).bind(f.id, u.id, now),
  ]);
  return json({ ok: true, username: f.username });
}

async function removeFriend(env: Env, u: User, username: string) {
  const f = await env.DB.prepare(`SELECT id FROM users WHERE username = ?`).bind(username).first<{ id: number }>();
  if (f) await env.DB.prepare(`DELETE FROM friends WHERE (user_id = ? AND friend_id = ?) OR (user_id = ? AND friend_id = ?)`).bind(u.id, f.id, f.id, u.id).run();
  return json({ ok: true });
}

async function postScore(req: Request, env: Env, u: User) {
  const b = await readJson<{ day?: string; points?: number; correct?: number; total?: number }>(req);
  const day = b?.day ?? '', points = Number(b?.points), correct = Number(b?.correct), total = Number(b?.total);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || Math.abs(Date.parse(`${day}T00:00:00Z`) - Date.parse(`${today()}T00:00:00Z`)) > 86400000) return err(400, 'Scores can only be posted for today.');
  if (![points, correct, total].every(Number.isInteger) || total < 1 || total > 30 || correct < 0 || correct > total || points < 0 || points > MAX_DAILY_POINTS) return err(400, 'Invalid score.');
  await env.DB.prepare(`INSERT INTO scores (user_id, day, points, correct, total, ts) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(user_id, day) DO UPDATE SET points = excluded.points, correct = excluded.correct, total = excluded.total, ts = excluded.ts WHERE excluded.points > scores.points`)
    .bind(u.id, day, points, correct, total, Date.now()).run();
  return json({ ok: true });
}

async function leaderboard(url: URL, env: Env, u: User) {
  const day = /^\d{4}-\d{2}-\d{2}$/.test(url.searchParams.get('day') ?? '') ? url.searchParams.get('day')! : today();
  const from = dayShift(day, -6);
  // me + friends who opted in to sharing
  const { results } = await env.DB.prepare(
    `WITH people AS (SELECT id, username FROM users WHERE id = ?1 UNION SELECT u.id, u.username FROM friends f JOIN users u ON u.id = f.friend_id WHERE f.user_id = ?1 AND u.share = 1)
     SELECT p.username, p.id = ?1 AS me,
       (SELECT points FROM scores s WHERE s.user_id = p.id AND s.day = ?2) AS today,
       (SELECT correct || '/' || total FROM scores s WHERE s.user_id = p.id AND s.day = ?2) AS today_acc,
       (SELECT COALESCE(SUM(points), 0) FROM scores s WHERE s.user_id = p.id AND s.day BETWEEN ?3 AND ?2) AS week,
       (SELECT COUNT(*) FROM scores s WHERE s.user_id = p.id AND s.day BETWEEN ?3 AND ?2) AS days
     FROM people p`).bind(u.id, day, from).all<{ username: string; me: number; today: number | null; today_acc: string | null; week: number; days: number }>();
  return json({ day, from, rows: results.map((r) => ({ username: r.username, me: !!r.me, today: r.today, todayAcc: r.today_acc, week: r.week, days: r.days })), sharing: !!u.share });
}

// ---------- router ----------
export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    const p = url.pathname;
    if (!p.startsWith('/api/')) return new Response('Not found', { status: 404 });
    if (p === '/api/health') return json({ ok: true, ai: false, reason: 'The hosted site runs without the Claude API.', sync: !!env.DB });
    if (!env.DB) return err(503, 'Sync is not configured on this deployment.');
    try {
      await ensureSchema(env.DB);
      const m = req.method;
      if (p === '/api/auth/signup' && m === 'POST') return await signup(req, env);
      if (p === '/api/auth/login' && m === 'POST') return await login(req, env);
      const u = await authed(req, env);
      if (!u) return err(401, 'Please sign in again.');
      if (p === '/api/auth/logout' && m === 'POST') {
        const tok = (req.headers.get('authorization') ?? '').slice(7);
        await env.DB.prepare(`DELETE FROM tokens WHERE token_hash = ?`).bind(await sha256(tok)).run();
        return json({ ok: true });
      }
      if (p === '/api/me' && m === 'GET') return json({ user: publicUser(u) });
      if (p === '/api/me' && m === 'POST') return await updateMe(req, env, u);
      if (p === '/api/account' && m === 'DELETE') return await deleteAccount(req, env, u);
      if (p === '/api/sync' && m === 'GET') return await getSync(env, u);
      if (p === '/api/sync' && m === 'PUT') return await putSync(req, env, u);
      if (p === '/api/friends' && m === 'GET') return await listFriends(env, u);
      if (p === '/api/friends' && m === 'POST') return await addFriend(req, env, u);
      if (p.startsWith('/api/friends/') && m === 'DELETE') return await removeFriend(env, u, decodeURIComponent(p.slice('/api/friends/'.length)));
      if (p === '/api/scores' && m === 'POST') return await postScore(req, env, u);
      if (p === '/api/leaderboard' && m === 'GET') return await leaderboard(url, env, u);
      return err(404, 'Unknown API route.');
    } catch (e) {
      console.error(e);
      return err(500, 'Server error. Please try again.');
    }
  },
} satisfies ExportedHandler<Env>;
